def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = me.count('D')

    last_opp = opp[-1]
    last_me = me[-1]

    if n >= 5 and opp_d == n:
        return 'D'
    if n >= 5 and opp_c == n:
        return 'C'

    coop_rate = opp_c / n

    if n >= 90:
        if coop_rate >= 0.7 and last_opp == 'C' and last_me == 'C':
            return 'D'
        if coop_rate <= 0.4:
            return 'D'
        return 'C'

    if n >= 70 and coop_rate >= 0.75 and last_opp == 'C':
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_d > opp_c:
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if opp_d >= opp_c + 2:
            return 'D'
        if n >= 3 and opp[-2] == 'D' and coop_rate < 0.6:
            return 'D'
        return 'D'

    if last_me == 'D' and last_opp == 'C':
        if coop_rate >= 0.6:
            return 'C'
        if opp_d >= opp_c:
            return 'D'
        return 'C'

    if coop_rate >= 0.75:
        if my_d == 0 and n > 30 and rng.random() < 0.04:
            return 'D'
        return 'C'

    if coop_rate >= 0.5:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    if coop_rate >= 0.3:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    if rng.random() < 0.1:
        return 'C'
    return 'D'
